select LAB_DOC_ID, GEN_SEQ  from 
(select LAB_DOC_ID, GEN_SEQ  from GEN_SEQUENCE where RAS_ELIG = 'Y' and (LAB_DOC_ID > #{DOC_ID} or LAB_DOC_ID in (select DOCUMENT_ID from RAS_SIERRA_PROCESS_ERRORS where ACTIVE_FLAG = 'R')) order by lab_Doc_id asc) 
where rownum < #{ROW_LIMIT}

