						   ,  #{lastAA, jdbcType=VARCHAR}
						   ,  #{firstNA, jdbcType=VARCHAR}
						   ,  #{lastNA, jdbcType=VARCHAR}
						   ,  #{matchPcnt, jdbcType=VARCHAR})

